{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Halcyon Threshold Incident Learning Record",
  "description": "Experimental record for learning from AI incidents and near misses. It is not a regulatory determination or an intake mechanism for confidential reports.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "record_id", "schema_version", "record_kind", "report_status", "synthetic",
    "title", "created_at", "updated_at", "reporter", "system", "event",
    "discovery", "harm", "safeguards", "causal_assessment", "responses",
    "evidence", "sharing", "follow_up", "revision_history"
  ],
  "properties": {
    "record_id": {"type": "string", "pattern": "^ILR-[A-Za-z0-9][A-Za-z0-9._-]{5,63}$"},
    "schema_version": {"const": "0.1.0"},
    "record_kind": {"enum": ["incident", "near_miss", "hazard_observation"]},
    "report_status": {"enum": ["preliminary", "updated", "final"]},
    "synthetic": {"type": "boolean", "description": "True only for wholly invented test records."},
    "title": {"type": "string", "minLength": 5, "maxLength": 200},
    "created_at": {"type": "string", "format": "date-time"},
    "updated_at": {"type": "string", "format": "date-time"},
    "reporter": {
      "type": "object", "additionalProperties": false,
      "required": ["relationship", "contact_route", "identity_withheld_from_public"],
      "properties": {
        "relationship": {"enum": ["developer", "deployer", "evaluator", "user", "third_party", "regulator", "other", "unknown"]},
        "contact_route": {"enum": ["direct", "regulator_portal", "other", "unknown"]},
        "identity_withheld_from_public": {"type": "boolean"}
      }
    },
    "system": {
      "type": "object", "additionalProperties": false,
      "required": ["model_name_disclosure", "model_reference", "deployment_context", "system_components", "autonomy", "affected_environment"],
      "properties": {
        "model_name_disclosure": {"enum": ["exact", "versioned_family", "family", "pseudonym", "unknown"]},
        "model_reference": {"type": "string", "minLength": 2, "maxLength": 200},
        "deployment_context": {"enum": ["health", "finance", "education", "employment", "critical_infrastructure", "government", "consumer", "enterprise", "research", "other", "unknown"]},
        "system_components": {"type": "array", "uniqueItems": true, "items": {"enum": ["model", "tool", "retrieval", "memory", "code_execution", "robotics", "human_workflow", "other"]}},
        "autonomy": {"enum": ["tool_only", "supervised_actions", "bounded_autonomy", "broad_autonomy", "unknown"]},
        "affected_environment": {"enum": ["testing", "limited_deployment", "production", "critical_infrastructure", "other", "unknown"]}
      }
    },
    "event": {
      "type": "object", "additionalProperties": false,
      "required": ["started_at", "ended_at", "time_precision", "description", "lifecycle_stage", "trigger"],
      "properties": {
        "started_at": {"$ref": "#/$defs/nullableDateTime"},
        "ended_at": {"$ref": "#/$defs/nullableDateTime"},
        "time_precision": {"enum": ["exact", "minute", "hour", "day", "range", "unknown"]},
        "description": {"type": "string", "minLength": 20, "maxLength": 10000},
        "lifecycle_stage": {"enum": ["evaluation", "red_team", "controlled_pilot", "production", "post_deployment", "other", "unknown"]},
        "trigger": {"enum": ["user_input", "environment", "model_initiated", "chained_system", "human_operator", "other", "unknown"]}
      }
    },
    "discovery": {
      "type": "object", "additionalProperties": false,
      "required": ["discovered_at", "discovered_by", "detection_delay"],
      "properties": {
        "discovered_at": {"$ref": "#/$defs/nullableDateTime"},
        "discovered_by": {"enum": ["monitoring", "user_report", "evaluator", "red_team", "internal_staff", "external_researcher", "regulator", "other", "unknown"]},
        "detection_delay": {"enum": ["minutes", "hours", "days", "weeks", "months", "not_applicable", "unknown"]}
      }
    },
    "harm": {
      "type": "object", "additionalProperties": false,
      "required": ["actual_severity", "categories", "affected_population", "reversibility", "potential_severity", "counterfactual"],
      "properties": {
        "actual_severity": {"$ref": "#/$defs/severity"},
