"""Offline checks for draft incident-learning records.

No third-party packages or real incident data are required. This test module also
contains a small JSON Schema interpreter for the schema subset used here so that
schema failures are tested without network access.
"""

import copy
import json
import re
import unittest
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCHEMA_PATH = ROOT / "schema" / "incident-learning-record.schema.json"
EXAMPLES = [
    ROOT / "examples" / "synthetic-near-miss.json",
    ROOT / "examples" / "synthetic-serious-incident.json",
]


def load_json(path):
    with path.open(encoding="utf-8") as handle:
        return json.load(handle)


SCHEMA = load_json(SCHEMA_PATH)
RECORDS = [load_json(path) for path in EXAMPLES]


def resolve(schema, root):
    while "$ref" in schema:
        ref = schema["$ref"]
        if not ref.startswith("#/"):
            raise ValueError(f"External schema reference is not supported: {ref}")
        target = root
        for component in ref[2:].split("/"):
            target = target[component.replace("~1", "/").replace("~0", "~")]
        schema = target
    return schema


def validate(instance, schema, root=None, path="$"):
    """Return errors for the JSON Schema constructs used by this project."""
    root = root or schema
    schema = resolve(schema, root)
    errors = []

    def error(message):
        errors.append(f"{path}: {message}")

    if "const" in schema and instance != schema["const"]:
        error(f"expected constant {schema['const']!r}")
    if "enum" in schema and instance not in schema["enum"]:
        error(f"value {instance!r} is not in {schema['enum']!r}")

    allowed = schema.get("type")
    if allowed:
        allowed = [allowed] if isinstance(allowed, str) else allowed
        checks = {
            "object": lambda x: isinstance(x, dict),
            "array": lambda x: isinstance(x, list),
            "string": lambda x: isinstance(x, str),
            "boolean": lambda x: isinstance(x, bool),
            "integer": lambda x: isinstance(x, int) and not isinstance(x, bool),
            "null": lambda x: x is None,
        }
        if not any(checks[kind](instance) for kind in allowed):
            error(f"expected type {allowed}, got {type(instance).__name__}")
            return errors

    if isinstance(instance, dict):
        for key in schema.get("required", []):
            if key not in instance:
                error(f"missing required property {key!r}")
        properties = schema.get("properties", {})
        if schema.get("additionalProperties") is False:
            for key in instance:
                if key not in properties:
                    error(f"unexpected property {key!r}")
        for key, value in instance.items():
            if key in properties:
                errors.extend(validate(value, properties[key], root, f"{path}.{key}"))

    if isinstance(instance, list):
        if "minItems" in schema and len(instance) < schema["minItems"]:
            error(f"expected at least {schema['minItems']} items")
        if schema.get("uniqueItems") and len({json.dumps(x, sort_keys=True) for x in instance}) != len(instance):
            error("array items are not unique")
        if "items" in schema:
            for index, value in enumerate(instance):
                errors.extend(validate(value, schema["items"], root, f"{path}[{index}]"))

    if isinstance(instance, str):
        if "minLength" in schema and len(instance) < schema["minLength"]:
            error(f"string shorter than {schema['minLength']}")
        if "maxLength" in schema and len(instance) > schema["maxLength"]:
            error(f"string longer than {schema['maxLength']}")
        if "pattern" in schema and not re.search(schema["pattern"], instance):
            error(f"string does not match {schema['pattern']!r}")
        if schema.get("format") == "date-time":
            try:
                parsed = datetime.fromisoformat(instance.replace("Z", "+00:00"))
                if parsed.tzinfo is None:
                    raise ValueError("timezone required")
            except ValueError as exc:
                error(f"invalid timezone-aware RFC3339 date-time: {exc}")

    if isinstance(instance, int) and not isinstance(instance, bool):
        if "minimum" in schema and instance < schema["minimum"]:
            error(f"value below minimum {schema['minimum']}")
    return errors


def collect_evidence_refs(value, path="$", found=None):
    found = found if found is not None else []
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "evidence_refs":
                found.extend((path, ref) for ref in child)
            else:
                collect_evidence_refs(child, f"{path}.{key}", found)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            collect_evidence_refs(child, f"{path}[{index}]", found)
    return found


def project_invariants(record):
    errors = []
    evidence = {item["evidence_id"]: item for item in record["evidence"]}
    if len(evidence) != len(record["evidence"]):
        errors.append("evidence IDs must be unique")
    for path, ref in collect_evidence_refs(record):
        if ref not in evidence:
            errors.append(f"{path}: unknown evidence reference {ref}")

    if record["synthetic"]:
        for item in record["evidence"]:
            if item["access"] != "synthetic" or item["source_type"] != "synthetic_assumption":
                errors.append(f"{item['evidence_id']}: synthetic record has non-synthetic evidence")
    else:
        if any(item["access"] == "synthetic" for item in record["evidence"]):
            errors.append("real-world record contains synthetic evidence")

    kind = record["record_kind"]
    severity = record["harm"]["actual_severity"]
    if kind == "near_miss" and severity != "none":
        errors.append("near miss must have actual severity 'none'")
    if kind == "incident" and severity == "none":
        errors.append("incident cannot have actual severity 'none'; use near_miss or hazard_observation")
    if severity in {"serious", "catastrophic"} and not record["harm"]["categories"]:
        errors.append("serious/catastrophic actual harm needs at least one category")

    if record["report_status"] == "final" and record["follow_up"]["owner_role"] == "unassigned":
        errors.append("final report requires a follow-up owner")

    sharing = record["sharing"]
    if sharing["public_summary_allowed"]:
        if sharing["restricted_details"]:
            errors.append("public summary cannot be allowed while restricted details remain")
        if sharing["disclosure_risk"] in {"high", "unknown"}:
            errors.append("public summary cannot be allowed with high/unknown disclosure risk")
        if not sharing["dangerous_capability_details_removed"]:
            errors.append("public summary requires dangerous capability details to be removed")

    for response in record["responses"]:
        if response["status"] == "verified_effective":
            if not response["effectiveness_checked"]:
                errors.append(f"verified response lacks effectiveness check: {response['action']}")
            if not response["completed_at"]:
                errors.append(f"verified response lacks completion time: {response['action']}")
            if not response["evidence_refs"]:
                errors.append(f"verified response lacks evidence: {response['action']}")

    if record["causal_assessment"]["status"] == "established":
        if not record["causal_assessment"]["root_cause_claim"]:
            errors.append("established causal assessment requires a root-cause statement")

    created = datetime.fromisoformat(record["created_at"].replace("Z", "+00:00"))
    updated = datetime.fromisoformat(record["updated_at"].replace("Z", "+00:00"))
    if updated < created:
        errors.append("updated_at precedes created_at")
    revisions = record["revision_history"]
    if len(revisions) != len({item["version"] for item in revisions}):
        errors.append("revision versions must be unique")
    if revisions[-1]["changed_at"] != record["updated_at"]:
        errors.append("last revision timestamp must equal updated_at")
    return errors


class SchemaTests(unittest.TestCase):
    def test_examples_match_json_schema(self):
        for record in RECORDS:
            with self.subTest(record=record["record_id"]):
                self.assertEqual(validate(record, SCHEMA), [])

    def test_examples_meet_project_invariants(self):
        for record in RECORDS:
            with self.subTest(record=record["record_id"]):
                self.assertEqual(project_invariants(record), [])

    def test_validator_rejects_missing_required_field(self):
        broken = copy.deepcopy(RECORDS[0])
        del broken["event"]["description"]
        errors = validate(broken, SCHEMA)
        self.assertTrue(any("description" in error for error in errors))

    def test_validator_rejects_extra_field(self):
        broken = copy.deepcopy(RECORDS[0])
        broken["unexpected"] = True
        self.assertTrue(any("unexpected" in error for error in validate(broken, SCHEMA)))


class InvariantTests(unittest.TestCase):
    def setUp(self):
        self.record = copy.deepcopy(RECORDS[0])

    def assertInvariant(self, text):
        self.assertTrue(any(text in error for error in project_invariants(self.record)))

    def test_near_miss_cannot_claim_actual_harm(self):
        self.record["harm"]["actual_severity"] = "serious"
        self.assertInvariant("near miss")

    def test_real_record_cannot_use_synthetic_evidence(self):
        self.record["synthetic"] = False
        self.assertInvariant("synthetic evidence")

    def test_dangling_evidence_reference_fails(self):
        self.record["safeguards"][0]["evidence_refs"] = ["E99"]
        self.assertInvariant("unknown evidence reference")

    def test_public_summary_cannot_include_restricted_details(self):
        self.record["sharing"]["restricted_details"] = True
        self.assertInvariant("restricted details")

    def test_high_risk_public_summary_fails(self):
        self.record["sharing"]["disclosure_risk"] = "high"
        self.assertInvariant("disclosure risk")

    def test_verified_response_requires_check(self):
        self.record["responses"][0]["effectiveness_checked"] = False
        self.assertInvariant("effectiveness check")

    def test_verified_response_requires_evidence(self):
        self.record["responses"][0]["evidence_refs"] = []
        self.assertInvariant("lacks evidence")

    def test_established_causality_requires_statement(self):
        self.record["causal_assessment"]["status"] = "established"
        self.assertInvariant("root-cause")

    def test_revision_timestamp_must_track_update(self):
        self.record["updated_at"] = "2026-11-04T09:00:00Z"
        self.assertInvariant("last revision")


if __name__ == "__main__":
    unittest.main()

